// ---------- math ----------
export function v3(x=0,y=0,z=0){return {x,y,z};}
export function vAdd(a,b){return {x:a.x+b.x,y:a.y+b.y,z:a.z+b.z};}
export function vSub(a,b){return {x:a.x-b.x,y:a.y-b.y,z:a.z-b.z};}
export function vScale(a,s){return {x:a.x*s,y:a.y*s,z:a.z*s};}
export function vDot(a,b){return a.x*b.x+a.y*b.y+a.z*b.z;}
export function vCross(a,b){return {x:a.y*b.z-a.z*b.y, y:a.z*b.x-a.x*b.z, z:a.x*b.y-a.y*b.x};}
export function vLen(a){return Math.sqrt(vDot(a,a));}
export function vNorm(a){const l=vLen(a)||1e-9;return vScale(a,1/l);}
export function vClone(a){return {x:a.x,y:a.y,z:a.z};}

export function qIdentity(){return {x:0,y:0,z:0,w:1};}
export function qMul(a,b){
  return {
    x: a.w*b.x + a.x*b.w + a.y*b.z - a.z*b.y,
    y: a.w*b.y - a.x*b.z + a.y*b.w + a.z*b.x,
    z: a.w*b.z + a.x*b.y - a.y*b.x + a.z*b.w,
    w: a.w*b.w - a.x*b.x - a.y*b.y - a.z*b.z
  };
}
export function qNorm(q){
  const l = Math.sqrt(q.x*q.x+q.y*q.y+q.z*q.z+q.w*q.w) || 1e-9;
  return {x:q.x/l,y:q.y/l,z:q.z/l,w:q.w/l};
}
export function qConj(q){return {x:-q.x,y:-q.y,z:-q.z,w:q.w};}
export function qRotateVec(q,v){
  const qv = {x:q.x,y:q.y,z:q.z};
  const uv = vCross(qv, v);
  const uuv = vCross(qv, uv);
  return vAdd(vAdd(v, vScale(uv, 2*q.w)), vScale(uuv, 2));
}
export function qFromAxisAngle(axis, angle){
  const l = vLen(axis);
  if (l < 1e-9) return qIdentity();
  const a = vScale(axis, 1/l);
  const s = Math.sin(angle/2);
  return qNorm({x:a.x*s,y:a.y*s,z:a.z*s,w:Math.cos(angle/2)});
}
export function qFromTwoVectors(u, v){
  const uu = vNorm(u), vv = vNorm(v);
  const d = Math.max(-1, Math.min(1, vDot(uu,vv)));
  if (d > 0.999999) return qIdentity();
  if (d < -0.999999) {
    let axis = vCross({x:1,y:0,z:0}, uu);
    if (vLen(axis) < 1e-6) axis = vCross({x:0,y:1,z:0}, uu);
    return qFromAxisAngle(axis, Math.PI);
  }
  const axis = vCross(uu, vv);
  return qNorm({x:axis.x,y:axis.y,z:axis.z, w: 1+d});
}
export function qAngleBetween(a,b){
  const rel = qMul(qConj(a), b);
  const w = Math.max(-1, Math.min(1, Math.abs(rel.w)));
  return 2*Math.acos(w);
}
export function qIntegrate(q, omega, dt){
  const wlen = vLen(omega);
  if (wlen < 1e-9) return qNorm(q);
  const dq = qFromAxisAngle(omega, wlen*dt);
  return qNorm(qMul(q, dq));
}
export function qAxisAngleError(qFrom, qTo){
  // returns small-rotation vector (body-ish) taking qFrom toward qTo
  const rel = qMul(qConj(qFrom), qTo);
  let w = rel.w; let x=rel.x,y=rel.y,z=rel.z;
  if (w < 0) { w=-w; x=-x; y=-y; z=-z; }
  const angle = 2*Math.acos(Math.max(-1,Math.min(1,w)));
  const s = Math.sqrt(Math.max(0,1-w*w));
  if (s < 1e-6) return {x:0,y:0,z:0};
  return {x: x/s*angle, y: y/s*angle, z: z/s*angle};
}

// ---------- seeded RNG ----------
export function mulberry32(seed){
  let a = seed >>> 0;
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
export function makeGaussian(rng){
  let spare = null;
  return function(sigma=1, mu=0){
    if (spare !== null) { const v = spare; spare = null; return mu + sigma*v; }
    let u,v,s;
    do { u = rng()*2-1; v = rng()*2-1; s = u*u+v*v; } while (s>=1 || s===0);
    const mul = Math.sqrt(-2*Math.log(s)/s);
    spare = v*mul;
    return mu + sigma*(u*mul);
  };
}

// ---------- small matrix helpers (6x6) ----------
export function mat6Identity(){ const m=[]; for(let i=0;i<6;i++){m.push(new Array(6).fill(0)); m[i][i]=1;} return m; }
export function matMulAB(A,B){ // A: r x k, B: k x c
  const r=A.length, k=B.length, c=B[0].length;
  const out = [];
  for(let i=0;i<r;i++){ out.push(new Array(c).fill(0));
    for(let j=0;j<c;j++){ let s=0; for(let t=0;t<k;t++) s+=A[i][t]*B[t][j]; out[i][j]=s; }
  }
  return out;
}
export function matTranspose(A){
  const r=A.length,c=A[0].length; const out=[];
  for(let j=0;j<c;j++){ out.push(new Array(r).fill(0)); for(let i=0;i<r;i++) out[j][i]=A[i][j]; }
  return out;
}
export function matInverseN(Ain){
  const n = Ain.length;
  const A = Ain.map(row=>row.slice());
  const I = mat6NIdentity(n);
  for (let col=0; col<n; col++){
    let piv = col;
    for (let r=col+1; r<n; r++) if (Math.abs(A[r][col]) > Math.abs(A[piv][col])) piv = r;
    if (piv !== col){ const t=A[col]; A[col]=A[piv]; A[piv]=t; const t2=I[col]; I[col]=I[piv]; I[piv]=t2; }
    let d = A[col][col]; if (Math.abs(d) < 1e-12) d = 1e-12;
    for (let c=0;c<n;c++){ A[col][c]/=d; I[col][c]/=d; }
    for (let r=0;r<n;r++){
      if (r===col) continue;
      const f = A[r][col];
      if (f===0) continue;
      for (let c=0;c<n;c++){ A[r][c]-=f*A[col][c]; I[r][c]-=f*I[col][c]; }
    }
  }
  return I;
}
function mat6NIdentity(n){ const m=[]; for(let i=0;i<n;i++){m.push(new Array(n).fill(0)); m[i][i]=1;} return m; }

