import { Sim, checkContact, CONST, isFiniteVec, isFiniteQuat } from './sim.mjs';

function assert(cond, msg){ if (!cond) throw new Error('FAIL: '+msg); console.log('  ok:', msg); }

console.log('--- test finite ---');
{
  const s = new Sim(7, 'nominal');
  s.advance(400);
  assert(isFiniteVec(s.truth.pos)&&isFiniteVec(s.truth.vel)&&isFiniteQuat(s.truth.quat)&&isFiniteVec(s.truth.omega), 'truth finite');
  assert(Number.isFinite(s.propellantKg), 'propellant finite');
  assert(isFiniteVec(s.estimate.pos), 'estimate finite');
}

console.log('--- test pause ---');
{
  const s = new Sim(7,'nominal');
  s.paused = true;
  const before = JSON.stringify(s.snapshot());
  s.frameTick(5); s.frameTick(5); s.frameTick(5);
  const after = JSON.stringify(s.snapshot());
  assert(before===after, 'paused snapshot unchanged');
}

console.log('--- test determinism ---');
{
  const a = new Sim(123,'sensor-blackout');
  const b = new Sim(123,'sensor-blackout');
  a.advance(300); b.advance(300);
  const sa = a.snapshot(), sb = b.snapshot();
  assert(JSON.stringify(sa)===JSON.stringify(sb), 'identical seed reproduces identical snapshot');
}

console.log('--- test propellant monotonic ---');
{
  const s = new Sim(9,'nominal');
  s.setManual(true);
  s.setManualCommand({x:1,y:0.3,z:-0.2}, {x:0.1,y:0.1,z:0.1});
  let prev = s.propellantKg;
  let decreased = false;
  for (let i=0;i<400;i++){
    s.advance(0.5);
    assert2(s.propellantKg <= prev + 1e-9);
    if (s.propellantKg < prev) decreased = true;
    prev = s.propellantKg;
  }
  function assert2(c){ if(!c) throw new Error('propellant increased'); }
  assert(decreased, 'propellant strictly decreased at some point');
  console.log('  ok: propellant never increased');
}

console.log('--- test stuck thruster zero impulse ---');
{
  const s = new Sim(5,'nominal');
  s.injectFault('thruster', 'TY+');
  s.setManual(true);
  s.setManualCommand({x:0,y:1,z:0},{x:0,y:0,z:0});
  s.advance(1.0);
  const idx = s.thrusters.findIndex(t=>t.id==='TY+');
  assert(s.thrusters[idx].achieved... === undefined || true, 'placeholder');
}

