console.log('--- 4. propellant monotonic ---');
{
  const s = new Sim(9,'nominal');
  s.setManual(true);
  s.setManualCommand({x:1,y:0.3,z:-0.2}, {x:0.1,y:0.1,z:0.1});
  let prev = s.propellantKg;
  let decreased = false;
  for (let i=0;i<400;i++){
    s.advance(0.5);
    if (s.propellantKg > prev + 1e-9) throw new Error('propellant increased at step '+i);
    if (s.propellantKg < prev) decreased = true;
    prev = s.propellantKg;
  }
  assert(decreased, 'propellant strictly decreased at some point, never increased');
}

console.log('--- 5. stuck thruster zero achieved impulse ---');
{
  const s = new Sim(5,'nominal');
  s.injectFault('thruster', 'TY+');
  s.setManual(true);
  s.setManualCommand({x:0,y:1,z:0},{x:0,y:0,z:0});
  s.advance(1.0);
  const idx = s.thrusters.findIndex(t=>t.id==='TY+');
  assert(s.thrusters[idx].commandedDuty > 0.05, 'thruster was commanded');
  assert(s.thrusters[idx].achievedDuty === 0, 'stuck thruster achieved duty is zero');
}

console.log('--- 6. blackout preserves/grows uncertainty ---');
{
  const s = new Sim(11,'nominal');
  s.advance(200);
  const sigmaBefore = s._navUncertaintyScalar();
  s.injectFault('lidar', true);
  s.injectFault('optical', true);
  let sigmaPrev = s._navUncertaintyScalar();
  let everDecreased = false;
  for (let i=0;i<200;i++){
    s.advance(0.5);
    const cur = s._navUncertaintyScalar();
    if (cur < sigmaPrev - 1e-9) everDecreased = true;
    sigmaPrev = cur;
  }
  assert(!everDecreased, 'uncertainty never decreased during blackout (no phantom measurement shrinkage)');
  assert(sigmaPrev >= sigmaBefore - 1e-9, 'uncertainty at end of blackout >= uncertainty at blackout start');
}

console.log('--- 7. abort creates safe retreat trend ---');
{
  const s = new Sim(21,'nominal');
  s.advance(900);
  const rangeAtAbort = s.snapshot().range;
  s.commandAbort();
  let maxRangeSeen = rangeAtAbort;
  for (let i=0;i<300;i++){
    s.advance(1.0);
    maxRangeSeen = Math.max(maxRangeSeen, s.snapshot().range);
  }
  assert(maxRangeSeen > rangeAtAbort + 1.0, 'range increased (retreated) after abort: '+rangeAtAbort.toFixed(2)+' -> '+maxRangeSeen.toFixed(2));
}

console.log('--- 8. contact rejected outside limits ---');
{
  const L = CONST.contactLimits;
  const bad1 = checkContact(0.2, 0.5, 0.01, 1, L);
  assert(!bad1.ok, 'rejects excessive closing rate');
  const bad2 = checkContact(0.2, 0.03, 0.5, 1, L);
  assert(!bad2.ok, 'rejects excessive lateral offset');
  const bad3 = checkContact(0.2, 0.03, 0.01, 30, L);
  assert(!bad3.ok, 'rejects excessive angle error');
  const good = checkContact(0.2, 0.03, 0.01, 1, L);
  assert(good.ok, 'accepts nominal contact conditions');
}

console.log('--- 9. nominal soft capture -> hard dock ---');
{
  const s = new Sim(42,'nominal');
  let docked = false;
  let softCap = false;
  const budget = 3600;
  const chunk = 5;
  let t = 0;
  while (t < budget && !docked){
    s.advance(chunk);
    t += chunk;
    if (s.guidance.phase === 'soft_capture') softCap = true;
    if (s.mission.docked) docked = true;
  }
  console.log('  final phase:', s.guidance.phase, 'met:', s.met.toFixed(1), 'range:', s.snapshot().range.toFixed(2));
  assert(softCap, 'reached soft_capture at some point');
  assert(docked, 'nominal scenario reaches hard_dock within budget');
}

console.log('\nALL TESTS PASSED');

