import {
  v3, vAdd, vSub, vScale, vDot, vCross, vLen, vNorm, vClone,
  qIdentity, qMul, qNorm, qConj, qRotateVec, qFromAxisAngle, qFromTwoVectors,
  qAngleBetween, qIntegrate, qAxisAngleError,
  mulberry32, makeGaussian
} from './engine.mjs';

export const FIXED_DT = 0.05;

export const CONST = {
  n: 0.0011,
  chaserMass: 350,
  chaserInertia: {x:70, y:100, z:90},
  targetInertia: {x:250, y:400, z:340},
  thrusterFmax: 6.0,
  isp: 220,
  g0: 9.80665,
  propCapacity: 6.0,
  keepOutRadius: 5.0,
  contactRange: 0.3,
  chaserPortOffset: {x:0.55,y:0,z:0},
  targetPortOffset: {x:0.9,y:0,z:0},
  waypoints: { hold: 25, proxStart: 25, finalStart: 8 },
  corridorHalfAngle: { proximity: 25*Math.PI/180, final: 9*Math.PI/180 },
  contactLimits: { contactRange: 0.3, minCloseRate: 0.005, maxCloseRate: 0.10, maxLateral: 0.18, maxAngleDeg: 6 },
  closeRateGate: { k: 0.012, min: 0.02, max: 0.35 },
};

// 8 corner thrusters canted along body diagonals of an asymmetric box (a!=b!=c
// so each corner's lever arm couples differently per axis): any single corner
// fires a blend of translation + torque, but symmetric 4-thruster subsets give
// exactly recoverable *bidirectional* pure force or pure torque about any axis
// (verified: for corners grouped by the sign of sy*sz, sx*sz or sx*sy, the two
// groups give +/- pure torque about x/y/z with zero net force, and grouping by
// sx, sy or sz sign gives +/- pure translation with zero net torque). Plus 4
// dedicated axial boosters for the dominant approach/retreat burn.
const CORNER = { a: 0.5, b: 0.4, c: 0.35 };
function buildThrusterDefs(){
  const defs = [];
  for (const sx of [1,-1]) for (const sy of [1,-1]) for (const sz of [1,-1]){
    const id = `C${sx>0?'+':'-'}${sy>0?'+':'-'}${sz>0?'+':'-'}`;
    const pos = { x: sx*CORNER.a, y: sy*CORNER.b, z: sz*CORNER.c };
    const dir = vNorm({ x:sx, y:sy, z:sz });
    defs.push({ id, pos, dir });
  }
  defs.push({id:'BX+a', pos:{x:0,y:0.1,z:0.3}, dir:{x:1,y:0,z:0}});
  defs.push({id:'BX+b', pos:{x:0,y:-0.1,z:-0.3}, dir:{x:1,y:0,z:0}});
  defs.push({id:'BX-a', pos:{x:0,y:0.1,z:-0.3}, dir:{x:-1,y:0,z:0}});
  defs.push({id:'BX-b', pos:{x:0,y:-0.1,z:0.3}, dir:{x:-1,y:0,z:0}});
  return defs;
}
const THRUSTER_DEFS = buildThrusterDefs();
const N_THRUSTERS = THRUSTER_DEFS.length;

function buildBColumns(){
  return THRUSTER_DEFS.map(t=>{
    const f = vScale(t.dir, CONST.thrusterFmax);
    const tq = vScale(vCross(t.pos, t.dir), CONST.thrusterFmax);
    return [f.x, f.y, f.z, tq.x, tq.y, tq.z];
  });
}
const B_COLS_FULL = buildBColumns();

// Box-constrained (duty in [0,1]) least-squares thruster allocation via
// projected Gauss-Seidel coordinate descent: each sweep finds the exact 1D
// optimum for one thruster holding the others fixed, then clips to [0,1] and
// updates the residual. Monotonically reduces achieved-wrench error and,
// unlike a raw pseudo-inverse, never needs an ad-hoc post-hoc clamp that would
// distort the achieved force/torque ratio.
function allocateNNLS(bCols, wrench, disabledMask, sweeps=18){
  const n = bCols.length;
  const duty = new Array(n).fill(0);
  const colNormSq = bCols.map((c,i)=> disabledMask[i] ? 1e-9 : (c[0]*c[0]+c[1]*c[1]+c[2]*c[2]+c[3]*c[3]+c[4]*c[4]+c[5]*c[5]) || 1e-9);
  const residual = wrench.slice();
  for (let sweep=0; sweep<sweeps; sweep++){
    for (let i=0;i<n;i++){
      if (disabledMask[i]) continue;
      const col = bCols[i];
      let dot = 0;
      for (let k=0;k<6;k++) dot += col[k]*residual[k];
      let newDuty = duty[i] + dot/colNormSq[i];
      if (newDuty < 0) newDuty = 0; else if (newDuty > 1) newDuty = 1;
      const delta = newDuty - duty[i];
      if (delta !== 0){
        for (let k=0;k<6;k++) residual[k] -= col[k]*delta;
        duty[i] = newDuty;
      }
    }
  }
  return duty;
}

export const SCENARIOS = {
  'nominal': {
    label: 'Nominal Rescue',
    tumbleDegPerSec: 1.3,
    faults: [],
  },
  'sensor-blackout': {
    label: 'Sensor Blackout',
    tumbleDegPerSec: 1.3,
    faults: [ { type:'blackout', atMET: 70, duration: 55 } ],
  },
  'stuck-thruster': {
    label: 'Stuck Thruster',
    tumbleDegPerSec: 1.3,
    faults: [ { type:'thruster-stuck', atMET: 25, thrusterId: 'TY+' } ],
  },
};

function clamp(v,lo,hi){ return Math.max(lo, Math.min(hi, v)); }
function deg2rad(d){ return d*Math.PI/180; }
function rad2deg(r){ return r*180/Math.PI; }

export class Sim {
  constructor(seed=1, scenario='nominal'){
    this.reset(seed, scenario);
  }

  reset(seed, scenario){
    if (scenario) this.scenario = scenario;
    if (!this.scenario) this.scenario = 'nominal';
    if (seed === undefined || seed === null) seed = this.seed || 1;
    this.seed = seed >>> 0;
    this.rng = mulberry32(this.seed);
    this.gauss = makeGaussian(this.rng);

    this.met = 0;
    this.paused = false;
    this.timeScale = 1;
    this.manualMode = false;
    this.manualCmd = { force: {x:0,y:0,z:0}, torque: {x:0,y:0,z:0} };

    const sc = SCENARIOS[this.scenario] || SCENARIOS.nominal;

    this.truth = {
      pos: {x:-42, y:6, z:2.5},
      vel: {x:0.01, y:0.015, z:0},
      quat: qFromAxisAngle({x:0.3,y:1,z:0.2}, deg2rad(35)),
      omega: {x:0.002,y:-0.001,z:0.001},
    };
    const tumbleRad = deg2rad(sc.tumbleDegPerSec);
    // spin mostly about the target's own docking-port boresight (body +X, the
    // min-inertia principal axis -> dynamically stable, only the intermediate
    // axis is chaotic). The port's pointing direction stays nearly fixed while
    // its roll continuously advances - a realistic "rotisserie" tumble that a
    // chaser can actually rendezvous with, with gentle nutation from the tiny
    // perpendicular component for visual character.
    const axis = vNorm({x: 1, y: 0.05*(this.rng()-0.5), z: 0.05*(this.rng()-0.5)});
    // orient the target so its docking port already faces roughly toward the
    // chaser's starting position, instead of an arbitrary side that would force
    // a transit straight through the keep-out sphere just to reach the corridor.
    const portFacing = qFromTwoVectors({x:1,y:0,z:0}, vNorm(this.truth.pos));
    this.target = {
      quat: portFacing,
      omega: vScale(axis, tumbleRad),
    };
    const c0 = this._corridorGeometry();
    this.corridorAxisSlow = vClone(c0.axis);
    this.corridorPortSlow = vClone(c0.portPos);

    this.propellantKg = CONST.propCapacity;

    this.thrusters = THRUSTER_DEFS.map(t=>({...t, commandedDuty:0, achievedDuty:0}));
    this.disabledThrusters = new Set();

    this.faults = {
      tumbleEnabled: true,
      lidarDropout: false,
      opticalDropout: false,
      stuckThrusterId: null,
      scripted: sc.faults.map(f=>({...f, done:false, active:false})),
    };

    this.fdir = { suspects:{}, detectedId:null, detectMET:null, windowResidual:0 };

    this.estimate = {
      pos: vAdd(this.truth.pos, {x:this.gauss(1.2),y:this.gauss(1.2),z:this.gauss(1.2)}),
      vel: vClone(this.truth.vel),
      quat: this.truth.quat,
      sigmaPos: {x:1.5,y:1.5,z:1.5},
      sigmaVel: {x:0.05,y:0.05,z:0.05},
      sigmaAtt: deg2rad(4),
      targetQuat: this.target.quat,
      targetOmega: vClone(this.target.omega),
      targetLock: true,
    };

    this.guidance = {
      phase: 'acquire',
      phaseStartMET: 0,
      lastReason: 'Mission start: acquiring target lock.',
      holdReason: null,
    };

    this.mission = {
      docked: false,
      aborted: false,
      softCaptured: false,
      captureAttempts: 0,
      abortReason: null,
    };

    this.safety = {
      keepOutViolation: false,
      corridorViolation: false,
      closingRateOk: true,
      alignmentOk: true,
      margins: { keepOut: 999, rate: 999, lateral: 999, angle: 999 },
    };

    this.prevRangeTruth = null;
    this.prevRangeEst = null;

    this.history = { t:[], range:[], closingRate:[], propellant:[], attErr:[], navUncertainty:[] };
    this.historyCap = 2400;

    this.log = [];
    this._pushLog('info', 'MISSION INIT', `Scenario "${(sc.label)}" loaded, seed ${this.seed}. Chaser holding at ${Math.abs(this.truth.pos.x).toFixed(1)} m standoff.`);
  }

  setScenario(name){
    if (!SCENARIOS[name]) return;
    this.reset(this.seed, name);
  }

  _pushLog(severity, tag, text){
    this.log.push({ t: this.met, phase: this.guidance.phase, severity, tag, text });
    if (this.log.length > 400) this.log.shift();
  }

  setManual(active){ this.manualMode = active; }
  setManualCommand(force, torque){
    this.manualCmd.force = force; this.manualCmd.torque = torque;
  }
  injectFault(type, value){
    if (type === 'tumble') this.faults.tumbleEnabled = value;
    if (type === 'lidar') this.faults.lidarDropout = value;
    if (type === 'optical') this.faults.opticalDropout = value;
    if (type === 'thruster') this.faults.stuckThrusterId = value || null;
  }
  commandAbort(){
    if (this.mission.docked) return;
    this.mission.aborted = true;
    this.guidance.phase = 'abort';
    this.guidance.phaseStartMET = this.met;
    this._pushLog('warn', 'ABORT', 'Abort commanded. Executing safe retreat along approach corridor.');
  }
  clearAbort(){
    if (!this.mission.aborted) return;
    this.mission.aborted = false;
    this.guidance.phase = 'far_approach';
    this.guidance.phaseStartMET = this.met;
    this._pushLog('info', 'RESUME', 'Abort cleared. Resuming autonomous approach.');
  }

  frameTick(dtSeconds){
    if (this.paused) return;
    this.advance(dtSeconds);
  }

  advance(seconds){
    let remaining = seconds;
    let guard = 0;
    while (remaining > 1e-9 && guard < 200000){
      const dt = Math.min(FIXED_DT, remaining);
      this._step(dt);
      remaining -= dt;
      guard++;
    }
  }

  step(dt){ this._step(dt); }

  _step(dt){
    this._updateScriptedFaults();

    const corridor = this._corridorGeometry();
    this._updateSlowCorridor(corridor, dt);
    const guideCorridor = { portPos: this.corridorPortSlow, axis: this.corridorAxisSlow };

    const rangesTruth = this._rangeAndLateral(this.truth.pos, this.truth.quat, corridor);
    const rangesEst = this._rangeAndLateral(this.estimate.pos, this.estimate.quat, corridor);
    const rangesEstGuide = this._rangeAndLateral(this.estimate.pos, this.estimate.quat, guideCorridor);

    const closingRateTruth = this.prevRangeTruth==null ? 0 : (this.prevRangeTruth - rangesTruth.range)/dt;
    const closingRateEst = this.prevRangeEst==null ? 0 : (this.prevRangeEst - rangesEst.range)/dt;
    this.prevRangeTruth = rangesTruth.range;
    this.prevRangeEst = rangesEst.range;

    this._updateGuidancePhase(rangesEst, rangesEstGuide, closingRateEst, corridor, guideCorridor);

    let desiredForce, desiredTorque;
    if (this.manualMode){
      desiredForce = qRotateVec(this.estimate.quat, this.manualCmd.force);
      desiredTorque = this.manualCmd.torque;
    } else {
      const activeCorridor = (this.guidance.phase==='final_corridor'||this.guidance.phase==='soft_capture'||this.guidance.phase==='hard_dock') ? corridor : guideCorridor;
      const activeRanges = (this.guidance.phase==='final_corridor'||this.guidance.phase==='soft_capture'||this.guidance.phase==='hard_dock') ? rangesEst : rangesEstGuide;
      const g = this._computeAutoGuidance(activeRanges, activeCorridor);
      desiredForce = g.force; desiredTorque = g.torque;
    }

    const alloc = this._allocateThrusters(desiredForce, desiredTorque);
    this._consumePropellant(alloc.achievedDuties, dt);
    this._integrateTruth(alloc.achievedForceLVLH, alloc.achievedTorqueBody, dt);
    this._integrateTargetTumble(dt);
    this._runSensorsAndEstimator(dt, corridor);
    this._runFdir(alloc, dt);

    const attErrDeg = rad2deg(qAngleBetween(this.truth.quat, this._desiredDockingQuat(corridor)));
    this._updateSafety(rangesTruth, closingRateTruth, corridor, attErrDeg);
    this._handleContact(rangesTruth, closingRateTruth, corridor, dt);

    this._pushHistory(rangesEst.range, closingRateEst, attErrDeg);

    this.met += dt;
  }

  _updateScriptedFaults(){
    for (const f of this.faults.scripted){
      if (f.done) continue;
      if (this.met >= f.atMET && !f.active){
        f.active = true;
        if (f.type === 'blackout'){
          this.faults.lidarDropout = true; this.faults.opticalDropout = true;
          this._pushLog('warn', 'SENSOR FAULT', 'Optical navigation and lidar dropped out. Estimator switching to open-loop propagation.');
        } else if (f.type === 'thruster-stuck'){
          this.faults.stuckThrusterId = f.thrusterId;
          this._pushLog('caution', 'ACTUATOR FAULT', `Thruster ${f.thrusterId} commanded but producing no measurable impulse.`);
        }
      }
      if (f.active && f.type === 'blackout' && this.met >= f.atMET + f.duration){
        f.active = false; f.done = true;
        this.faults.lidarDropout = false; this.faults.opticalDropout = false;
        this._pushLog('info', 'SENSOR RECOVERY', 'Optical and lidar returns restored. Estimator uncertainty contracting.');
      }
      if (f.active && f.type === 'thruster-stuck') f.done = true;
    }
  }

  _updateSlowCorridor(corridor, dt){
    const tau = 90;
    const alpha = clamp(dt/tau, 0, 1);
    this.corridorAxisSlow = vNorm(vAdd(this.corridorAxisSlow, vScale(vSub(corridor.axis, this.corridorAxisSlow), alpha)));
    this.corridorPortSlow = vAdd(this.corridorPortSlow, vScale(vSub(corridor.portPos, this.corridorPortSlow), alpha));
  }

  _corridorGeometry(){
    const targetPortPos = qRotateVec(this.target.quat, CONST.targetPortOffset);
    const axis = vNorm(qRotateVec(this.target.quat, {x:1,y:0,z:0}));
    return { portPos: targetPortPos, axis };
  }

  _rangeAndLateral(chaserPos, chaserQuat, corridor){
    const chaserPortPos = vAdd(chaserPos, qRotateVec(chaserQuat, CONST.chaserPortOffset));
    const delta = vSub(corridor.portPos, chaserPortPos);
    const range = vLen(delta);
    const along = vDot(delta, corridor.axis);
    const lateralVec = vSub(delta, vScale(corridor.axis, along));
    const lateral = vLen(lateralVec);
    let angleFromAxis = 0;
    if (range > 1e-6) angleFromAxis = Math.acos(clamp(along/range, -1, 1));
    return { chaserPortPos, delta, range, along, lateral, angleFromAxis };
  }

  _desiredDockingQuat(corridor){
    // chaser +X should point opposite the corridor axis (facing the port)
    return qFromTwoVectors({x:1,y:0,z:0}, vScale(corridor.axis, -1));
  }

  _updateGuidancePhase(rangesEst, rangesEstGuide, closingRateEst, corridor, guideCorridor){
    const g = this.guidance;
    if (this.mission.aborted || g.phase === 'abort'){ g.phase = 'abort'; return; }
    if (g.phase === 'hard_dock') return;
    const elapsedInPhase = this.met - g.phaseStartMET;

    const transition = (next, reason)=>{
      g.phase = next; g.phaseStartMET = this.met; g.lastReason = reason; g.holdReason = null;
      this._pushLog('info', 'PHASE', reason);
    };

    switch(g.phase){
      case 'acquire':
        if (elapsedInPhase > 4){
          transition('far_approach', 'Target lock established. Beginning far-field approach toward hold point.');
        }
        break;
      case 'far_approach':
        if (rangesEstGuide.range <= CONST.waypoints.hold + 1.0 && Math.abs(closingRateEst) < 0.15){
          transition('hold_point', `Reached hold point at ${rangesEstGuide.range.toFixed(1)} m. Stationkeeping to verify navigation and attitude sync.`);
        }
        break;
      case 'hold_point': {
        const navGood = this._navUncertaintyScalar() < 0.9;
        const attErrDeg = rad2deg(qAngleBetween(this.estimate.quat, this._desiredDockingQuat(guideCorridor)));
        if (navGood && attErrDeg < 20 && elapsedInPhase > 8){
          transition('proximity_approach', 'Navigation solid and attitude synced. Cleared for proximity approach.');
        } else if (!navGood){
          g.holdReason = 'Holding: navigation uncertainty above threshold for proximity clearance.';
        }
        break;
      }
      case 'proximity_approach': {
        const navBad = this._navUncertaintyScalar() > 1.6;
        if (navBad){
          transition('hold_point', 'Navigation uncertainty exceeded safe threshold during proximity ops. Reverting to hold point.');
          break;
        }
        if (rangesEst.range <= CONST.waypoints.finalStart + 0.5 && rangesEst.lateral < 1.5){
          transition('final_corridor', `Entering final approach corridor at ${rangesEst.range.toFixed(1)} m.`);
        }
        break;
      }
      case 'final_corridor': {
        const navBad = this._navUncertaintyScalar() > 1.4;
        if (navBad){
          transition('hold_point', 'Navigation degraded inside final corridor. Retreating to hold point for safety.');
          break;
        }
        break; // contact handled in _handleContact
      }
      case 'soft_capture':
        break;
    }
  }

  _navUncertaintyScalar(){
    const e = this.estimate;
    return (e.sigmaPos.x+e.sigmaPos.y+e.sigmaPos.z)/3;
  }

  _computeAutoGuidance(rangesEst, corridor){
    const phase = this.guidance.phase;
    const m = CONST.chaserMass;
    const pos = this.estimate.pos, vel = this.estimate.vel;
    const n = CONST.n;
    const naturalAccel = { x: 2*n*vel.y+3*n*n*pos.x, y: -2*n*vel.x, z: -n*n*pos.z };

    let vDes = {x:0,y:0,z:0};
    let posErrGain = 0;
    let velGain = 0.9;

    const towardPort = vNorm(rangesEst.delta);

    if (phase === 'abort'){
      const target = vAdd(corridor.portPos, vScale(corridor.axis, CONST.waypoints.hold*1.6));
      const err = vSub(target, this.estimate.pos);
      vDes = vScale(vNorm(err), clamp(vLen(err)/120, 0.02, 0.25));
      velGain = 0.7;
    } else if (phase === 'acquire'){
      vDes = {x:0,y:0,z:0}; velGain = 0.6;
    } else if (phase === 'far_approach'){
      const wp = vAdd(corridor.portPos, vScale(corridor.axis, CONST.waypoints.hold));
      const err = vSub(wp, this.estimate.pos);
      const dist = vLen(err);
      const speed = clamp(dist/260, 0.03, 0.5);
      vDes = dist>0.05 ? vScale(vNorm(err), speed) : {x:0,y:0,z:0};
      velGain = 0.8;
    } else if (phase === 'hold_point'){
      const wp = vAdd(corridor.portPos, vScale(corridor.axis, CONST.waypoints.hold));
      posErrGain = 0.02;
      vDes = {x:0,y:0,z:0};
      const err = vSub(wp, this.estimate.pos);
      vDes = vScale(err, 0.02);
      velGain = 1.0;
    } else if (phase === 'proximity_approach'){
      const wp = vAdd(corridor.portPos, vScale(corridor.axis, CONST.waypoints.finalStart));
      const alongErr = vDot(vSub(wp, this.estimate.pos), corridor.axis);
      const lateralVec = vSub(vSub(wp, this.estimate.pos), vScale(corridor.axis, alongErr));
      const gateAlong = clamp(rangesEst.range*CONST.closeRateGate.k, CONST.closeRateGate.min, CONST.closeRateGate.max);
      const speedAlong = clamp(alongErr/200, -gateAlong, gateAlong);
      const gateLateral = 0.22;
      let vLat = vScale(lateralVec, 0.06);
      if (vLen(vLat) > gateLateral) vLat = vScale(vNorm(vLat), gateLateral);
      vDes = vAdd(vScale(corridor.axis, speedAlong), vLat);
      velGain = 0.9;
    } else if (phase === 'final_corridor'){
      const alongErr = vDot(vSub(corridor.portPos, rangesEst.chaserPortPos), corridor.axis);
      const lateralVec = vSub(vSub(corridor.portPos, rangesEst.chaserPortPos), vScale(corridor.axis, alongErr));
      const gateAlong = clamp(rangesEst.range*CONST.closeRateGate.k*0.6, 0.01, 0.09);
      const speedAlong = clamp(alongErr/160, -gateAlong, gateAlong);
      const gateLateral = 0.2;
      let vLat = vScale(lateralVec, 0.16);
      if (vLen(vLat) > gateLateral) vLat = vScale(vNorm(vLat), gateLateral);
      vDes = vAdd(vScale(corridor.axis, speedAlong), vLat);
      velGain = 1.1;
    } else if (phase === 'soft_capture' || phase === 'hard_dock'){
      vDes = {x:0,y:0,z:0}; velGain = 1.4; posErrGain = 0.05;
    }

    let forceMag;
    if (phase==='far_approach') forceMag = 3.4;
    else if (phase==='hold_point') forceMag = 1.6;
    else if (phase==='proximity_approach') forceMag = 2.2;
    else if (phase==='final_corridor') forceMag = 1.2;
    else if (phase==='soft_capture'||phase==='hard_dock') forceMag = 1.0;
    else forceMag = 2.0;

    let force = vScale({
      x: -naturalAccel.x + velGain*(vDes.x - this.estimate.vel.x),
      y: -naturalAccel.y + velGain*(vDes.y - this.estimate.vel.y),
      z: -naturalAccel.z + velGain*(vDes.z - this.estimate.vel.z),
    }, m);
    const fl = vLen(force);
    if (fl > forceMag*12) force = vScale(force, (forceMag*12)/fl);

    const qDes = this._desiredDockingQuat(corridor);
    const axisErr = qAxisAngleError(this.estimate.quat, qDes);
    const I = CONST.chaserInertia;
    const omega = this.estimate.omega || {x:0,y:0,z:0};
    const Kp_att = (phase==='final_corridor'||phase==='soft_capture'||phase==='hard_dock') ? 3.2 : 1.6;
    const Kd_att = (phase==='final_corridor'||phase==='soft_capture'||phase==='hard_dock') ? 6.5 : 4.0;
    const gyro = vCross(omega, {x:I.x*omega.x, y:I.y*omega.y, z:I.z*omega.z});
    let torque = {
      x: I.x*(Kp_att*axisErr.x - Kd_att*omega.x) + gyro.x,
      y: I.y*(Kp_att*axisErr.y - Kd_att*omega.y) + gyro.y,
      z: I.z*(Kp_att*axisErr.z - Kd_att*omega.z) + gyro.z,
    };
    const tl = vLen(torque);
    const maxT = 4.0;
    if (tl > maxT) torque = vScale(torque, maxT/tl);

    return { force, torque };
  }

  _allocateThrusters(desiredForceLVLH, desiredTorqueBody){
    const desiredForceBody = qRotateVec(qConj(this.truth.quat), desiredForceLVLH);
    const wrench = [desiredForceBody.x, desiredForceBody.y, desiredForceBody.z, desiredTorqueBody.x, desiredTorqueBody.y, desiredTorqueBody.z];

    const disabledMask = THRUSTER_DEFS.map(t=> this.disabledThrusters.has(t.id));
    const duty = allocateNNLS(B_COLS_FULL, wrench, disabledMask);

    const achieved = new Array(N_THRUSTERS).fill(0);
    for (let i=0;i<N_THRUSTERS;i++){
      let d = duty[i];
      const isStuck = this.thrusters[i].id === this.faults.stuckThrusterId;
      this.thrusters[i].commandedDuty = d;
      if (isStuck) d = 0;
      achieved[i] = d;
      this.thrusters[i].achievedDuty = d;
    }

    let achievedForceBody = {x:0,y:0,z:0};
    let achievedTorqueBody = {x:0,y:0,z:0};
    for (let i=0;i<N_THRUSTERS;i++){
      const f = vScale(THRUSTER_DEFS[i].dir, CONST.thrusterFmax*achieved[i]);
      const tq = vScale(vCross(THRUSTER_DEFS[i].pos, THRUSTER_DEFS[i].dir), CONST.thrusterFmax*achieved[i]);
      achievedForceBody = vAdd(achievedForceBody, f);
      achievedTorqueBody = vAdd(achievedTorqueBody, tq);
    }
    const achievedForceLVLH = qRotateVec(this.truth.quat, achievedForceBody);

    return { achievedDuties: achieved, achievedForceLVLH, achievedTorqueBody, desiredWrench: wrench };
  }

  _consumePropellant(achievedDuties, dt){
    let totalThrust = 0;
    for (let i=0;i<12;i++) totalThrust += CONST.thrusterFmax*achievedDuties[i];
    const mdot = totalThrust/(CONST.isp*CONST.g0);
    this.propellantKg = Math.max(0, this.propellantKg - mdot*dt);
  }

  _integrateTruth(forceLVLH, torqueBody, dt){
    const m = CONST.chaserMass;
    const n = CONST.n;
    const s = this.truth;
    const deriv = (pos, vel)=>({
      dpos: vClone(vel),
      dvel: {
        x: 2*n*vel.y + 3*n*n*pos.x + forceLVLH.x/m,
        y: -2*n*vel.x + forceLVLH.y/m,
        z: -n*n*pos.z + forceLVLH.z/m,
      }
    });
    const k1 = deriv(s.pos, s.vel);
    const k2 = deriv(vAdd(s.pos, vScale(k1.dpos, dt/2)), vAdd(s.vel, vScale(k1.dvel, dt/2)));
    const k3 = deriv(vAdd(s.pos, vScale(k2.dpos, dt/2)), vAdd(s.vel, vScale(k2.dvel, dt/2)));
    const k4 = deriv(vAdd(s.pos, vScale(k3.dpos, dt)), vAdd(s.vel, vScale(k3.dvel, dt)));
    s.pos = vAdd(s.pos, vScale(vAdd(vAdd(k1.dpos, vScale(k2.dpos,2)), vAdd(vScale(k3.dpos,2), k4.dpos)), dt/6));
    s.vel = vAdd(s.vel, vScale(vAdd(vAdd(k1.dvel, vScale(k2.dvel,2)), vAdd(vScale(k3.dvel,2), k4.dvel)), dt/6));

    const I = CONST.chaserInertia;
    const omegaDeriv = (omega)=>{
      const Iomega = {x:I.x*omega.x, y:I.y*omega.y, z:I.z*omega.z};
      const gyro = vCross(omega, Iomega);
      return { x:(torqueBody.x-gyro.x)/I.x, y:(torqueBody.y-gyro.y)/I.y, z:(torqueBody.z-gyro.z)/I.z };
    };
    const o1 = omegaDeriv(s.omega);
    const o2 = omegaDeriv(vAdd(s.omega, vScale(o1, dt/2)));
    const o3 = omegaDeriv(vAdd(s.omega, vScale(o2, dt/2)));
    const o4 = omegaDeriv(vAdd(s.omega, vScale(o3, dt)));
    const omegaNew = vAdd(s.omega, vScale(vAdd(vAdd(o1, vScale(o2,2)), vAdd(vScale(o3,2), o4)), dt/6));
    const omegaAvg = vScale(vAdd(s.omega, omegaNew), 0.5);
    s.quat = qIntegrate(s.quat, omegaAvg, dt);
    s.omega = omegaNew;
  }

  _integrateTargetTumble(dt){
    if (!this.faults.tumbleEnabled){ return; }
    const I = CONST.targetInertia;
    const t = this.target;
    const omegaDeriv = (omega)=>{
      const Iomega = {x:I.x*omega.x, y:I.y*omega.y, z:I.z*omega.z};
      const gyro = vCross(omega, Iomega);
      return { x:-gyro.x/I.x, y:-gyro.y/I.y, z:-gyro.z/I.z };
    };
    const o1 = omegaDeriv(t.omega);
    const o2 = omegaDeriv(vAdd(t.omega, vScale(o1, dt/2)));
    const o3 = omegaDeriv(vAdd(t.omega, vScale(o2, dt/2)));
    const o4 = omegaDeriv(vAdd(t.omega, vScale(o3, dt)));
    const omegaNew = vAdd(t.omega, vScale(vAdd(vAdd(o1, vScale(o2,2)), vAdd(vScale(o3,2), o4)), dt/6));
    const omegaAvg = vScale(vAdd(t.omega, omegaNew), 0.5);
    t.quat = qIntegrate(t.quat, omegaAvg, dt);
    t.omega = omegaNew;
  }

  _runSensorsAndEstimator(dt, corridor){
    const e = this.estimate;
    const lidarActive = !this.faults.lidarDropout;
    const opticalActive = !this.faults.opticalDropout;

    // prediction (uses same known applied accel implicitly via velocity persistence + natural dynamics)
    const n = CONST.n;
    const natAccel = { x: 2*n*e.vel.y+3*n*n*e.pos.x, y:-2*n*e.vel.x, z:-n*n*e.pos.z };
    e.vel = vAdd(e.vel, vScale(natAccel, dt));
    e.pos = vAdd(e.pos, vScale(e.vel, dt));

    const qProcess = 0.0009;
    e.sigmaPos = { x: Math.sqrt(e.sigmaPos.x**2 + (qProcess*dt)**2)+0*e.sigmaPos.x*0.0006,
                    y: Math.sqrt(e.sigmaPos.y**2 + (qProcess*dt)**2),
                    z: Math.sqrt(e.sigmaPos.z**2 + (qProcess*dt)**2) };
    e.sigmaPos = { x: e.sigmaPos.x*(1+0.0008), y: e.sigmaPos.y*(1+0.0008), z: e.sigmaPos.z*(1+0.0008) };
    e.sigmaVel = { x: e.sigmaVel.x*(1+0.0006)+1e-5, y: e.sigmaVel.y*(1+0.0006)+1e-5, z: e.sigmaVel.z*(1+0.0006)+1e-5 };
    e.sigmaAtt = e.sigmaAtt*(1+0.0006) + 1e-6;

    if (lidarActive){
      const measPos = vAdd(this.truth.pos, {x:this.gauss(0.06),y:this.gauss(0.06),z:this.gauss(0.06)});
      const R = 0.06;
      ['x','y','z'].forEach(ax=>{
        const P = e.sigmaPos[ax]**2;
        const K = P/(P+R*R);
        e.pos[ax] = e.pos[ax] + K*(measPos[ax]-e.pos[ax]);
        e.sigmaPos[ax] = Math.sqrt((1-K)*P);
      });
      const measVel = vAdd(this.truth.vel, {x:this.gauss(0.004),y:this.gauss(0.004),z:this.gauss(0.004)});
      const Rv = 0.004;
      ['x','y','z'].forEach(ax=>{
        const P = e.sigmaVel[ax]**2;
        const K = P/(P+Rv*Rv);
        e.vel[ax] = e.vel[ax] + K*(measVel[ax]-e.vel[ax]);
        e.sigmaVel[ax] = Math.sqrt((1-K)*P);
      });
    } else if (opticalActive){
      const measPos = vAdd(this.truth.pos, {x:this.gauss(0.9),y:this.gauss(0.9),z:this.gauss(0.9)});
      const R = 0.9;
      ['x','y','z'].forEach(ax=>{
        const P = e.sigmaPos[ax]**2;
        const K = P/(P+R*R);
        e.pos[ax] = e.pos[ax] + K*(measPos[ax]-e.pos[ax]);
        e.sigmaPos[ax] = Math.sqrt((1-K)*P);
      });
    }

    if (opticalActive){
      e.quat = this.truth.quat;
      e.sigmaAtt = Math.max(deg2rad(0.6), e.sigmaAtt*0.7);
      e.targetQuat = this.target.quat;
      e.targetOmega = vClone(this.target.omega);
      e.targetLock = true;
    } else {
      e.quat = qIntegrate(e.quat, this.truth.omega, dt);
      e.targetQuat = qIntegrate(e.targetQuat, e.targetOmega, dt);
      e.targetLock = false;
    }
    e.omega = vClone(this.truth.omega);
  }

  _runFdir(alloc, dt){
    if (this.faults.stuckThrusterId && this.disabledThrusters.size===0 && !this.fdir.detectedId){
      const id = this.faults.stuckThrusterId;
      const idx = THRUSTER_DEFS.findIndex(t=>t.id===id);
      const commandedHigh = this.thrusters[idx].commandedDuty > 0.12;
      if (commandedHigh){
        this.fdir.windowResidual += dt;
      } else {
        this.fdir.windowResidual = Math.max(0, this.fdir.windowResidual-dt*0.5);
      }
      if (this.fdir.windowResidual > 1.2){
        this.fdir.detectedId = id;
        this.fdir.detectMET = this.met;
        this.disabledThrusters.add(id);
        this._pushLog('warn', 'FDIR', `Fault isolated to thruster ${id}. Reallocating RCS authority to remaining thrusters.`);
      }
    }
  }

  _updateSafety(rangesTruth, closingRateTruth, corridor, attErrDeg){
    const s = this.safety;
    const inSphere = rangesTruth.range < CONST.keepOutRadius;
    const halfAngle = (this.guidance.phase==='final_corridor'||this.guidance.phase==='soft_capture') ? CONST.corridorHalfAngle.final : CONST.corridorHalfAngle.proximity;
    const insideCorridor = rangesTruth.angleFromAxis < halfAngle;
    s.keepOutViolation = inSphere && !insideCorridor;
    const gate = clamp(rangesTruth.range*CONST.closeRateGate.k, CONST.closeRateGate.min, CONST.closeRateGate.max);
    s.closingRateOk = closingRateTruth <= gate*1.4;
    s.alignmentOk = attErrDeg < 35;
    s.margins = {
      keepOut: inSphere ? (insideCorridor ? 1 : 0) : (rangesTruth.range - CONST.keepOutRadius),
      rate: gate*1.4 - closingRateTruth,
      lateral: CONST.contactLimits.maxLateral - rangesTruth.lateral,
      angle: CONST.contactLimits.maxAngleDeg - attErrDeg,
    };
    if (s.keepOutViolation && !this.mission.aborted && this.guidance.phase!=='abort' && rangesTruth.range > CONST.contactRange){
      this.commandAbort();
      this.mission.abortReason = 'keep-out violation';
      this._pushLog('caution', 'SAFETY', 'Keep-out sphere violated outside approach corridor. Autonomous abort triggered.');
    }
  }

  _handleContact(rangesTruth, closingRateTruth, corridor, dt){
    if (this.mission.docked) return;
    if (rangesTruth.range > CONST.contactRange) return;
    if (this.guidance.phase === 'abort') return;

    const attErrDeg = rad2deg(qAngleBetween(this.truth.quat, this._desiredDockingQuat(corridor)));
    const result = checkContact(rangesTruth.range, closingRateTruth, rangesTruth.lateral, attErrDeg, CONST.contactLimits);
    this.mission.captureAttempts++;

    if (result.ok){
      if (this.guidance.phase !== 'soft_capture'){
        this.guidance.phase = 'soft_capture';
        this.guidance.phaseStartMET = this.met;
        this.mission.softCaptured = true;
        this._pushLog('info', 'CONTACT', `Soft capture achieved: range ${rangesTruth.range.toFixed(2)} m, closing ${closingRateTruth.toFixed(3)} m/s, align ${attErrDeg.toFixed(1)} deg.`);
      }
      const stableFor = this.met - this.guidance.phaseStartMET;
      this.truth.vel = vScale(this.truth.vel, 0.85);
      this.truth.omega = vScale(this.truth.omega, 0.85);
      if (stableFor > 3.0){
        this.guidance.phase = 'hard_dock';
        this.mission.docked = true;
        this._pushLog('info', 'DOCK', 'Rigid docking confirmed. Hard mate achieved, mission complete.');
      }
    } else {
      const normal = vNorm(rangesTruth.delta);
      const vAlong = vDot(this.truth.vel, normal);
      if (vAlong > 0){
        this.truth.vel = vSub(this.truth.vel, vScale(normal, vAlong*1.35));
      }
      const push = CONST.contactRange*1.15 - rangesTruth.range;
      if (push > 0) this.truth.pos = vSub(this.truth.pos, vScale(normal, push));
      this._pushLog('caution', 'CONTACT', `Capture rejected (${result.reason}) at range ${rangesTruth.range.toFixed(2)} m. Rebounding for re-attempt.`);
      if (attErrDeg > 45 || rangesTruth.lateral > CONST.keepOutRadius*0.6){
        this.commandAbort();
        this.mission.abortReason = 'unsafe contact geometry';
      }
    }
  }

  _pushHistory(range, closingRate, attErrDeg){
    const h = this.history;
    h.t.push(this.met);
    h.range.push(range);
    h.closingRate.push(closingRate);
    h.propellant.push(this.propellantKg);
    h.attErr.push(attErrDeg);
    h.navUncertainty.push(this._navUncertaintyScalar());
    if (h.t.length > this.historyCap){
      h.t.shift(); h.range.shift(); h.closingRate.shift(); h.propellant.shift(); h.attErr.shift(); h.navUncertainty.shift();
    }
  }

  snapshot(){
    const corridor = this._corridorGeometry();
    const rangesTruth = this._rangeAndLateral(this.truth.pos, this.truth.quat, corridor);
    const rangesEst = this._rangeAndLateral(this.estimate.pos, this.estimate.quat, corridor);
    return {
      met: this.met,
      seed: this.seed,
      scenario: this.scenario,
      paused: this.paused,
      manualMode: this.manualMode,
      truth: {
        pos: vClone(this.truth.pos), vel: vClone(this.truth.vel),
        quat: {...this.truth.quat}, omega: vClone(this.truth.omega),
        targetQuat: {...this.target.quat}, targetOmega: vClone(this.target.omega),
      },
      estimate: {
        pos: vClone(this.estimate.pos), vel: vClone(this.estimate.vel),
        quat: {...this.estimate.quat}, sigmaPos: {...this.estimate.sigmaPos}, sigmaVel: {...this.estimate.sigmaVel},
        sigmaAtt: this.estimate.sigmaAtt, targetLock: this.estimate.targetLock,
      },
      guidance: { phase: this.guidance.phase, holdReason: this.guidance.holdReason, lastReason: this.guidance.lastReason },
      actuators: {
        propellantKg: this.propellantKg, propellantPct: this.propellantKg/CONST.propCapacity,
        thrusters: this.thrusters.map(t=>({id:t.id, commanded:t.commandedDuty, achieved:t.achievedDuty, stuck: t.id===this.faults.stuckThrusterId})),
      },
      safety: { ...this.safety, margins: {...this.safety.margins} },
      sensors: { lidarActive: !this.faults.lidarDropout, opticalActive: !this.faults.opticalDropout },
      faults: { ...this.faults, scripted: undefined },
      mission: { ...this.mission },
      range: rangesTruth.range,
      rangeEst: rangesEst.range,
      lateral: rangesTruth.lateral,
    };
  }
}

export function checkContact(range, closingRate, lateralOffset, angleErrorDeg, limits){
  if (range > limits.contactRange) return { ok:false, reason:'out-of-range' };
  if (closingRate < limits.minCloseRate) return { ok:false, reason:'closing-rate-too-low' };
  if (closingRate > limits.maxCloseRate) return { ok:false, reason:'closing-rate-too-high' };
  if (lateralOffset > limits.maxLateral) return { ok:false, reason:'lateral-offset' };
  if (angleErrorDeg > limits.maxAngleDeg) return { ok:false, reason:'angle-misalign' };
  return { ok:true, reason:'nominal' };
}

export function isFiniteVec(v){ return Number.isFinite(v.x)&&Number.isFinite(v.y)&&Number.isFinite(v.z); }
export function isFiniteQuat(q){ return Number.isFinite(q.x)&&Number.isFinite(q.y)&&Number.isFinite(q.z)&&Number.isFinite(q.w); }

