_handleContact(rangesTruth, closingRateTruth, corridor, dt){
  if (this.mission.docked) return;
  if (this.guidance.phase === 'abort') return;

  // Already latched in soft capture: the mechanism is actively damping
  // relative motion toward zero, so re-applying the *initial* contact gate
  // (which requires a minimum closing rate) would immediately "reject" the
  // very capture it just confirmed. Only watch for gross containment loss.
  if (this.guidance.phase === 'soft_capture'){
    if (rangesTruth.range > CONST.contactRange*3.5){
      this.guidance.phase = 'final_corridor';
      this.guidance.phaseStartMET = this.met;
      this._pushLog('caution', 'CONTACT', 'Soft capture containment lost. Re-attempting final approach.');
      return;
    }
    this.truth.vel = vScale(this.truth.vel, 0.85);
    this.truth.omega = vScale(this.truth.omega, 0.85);
    const stableFor = this.met - this.guidance.phaseStartMET;
    if (stableFor > 3.0){
      this.guidance.phase = 'hard_dock';
      this.mission.docked = true;
      this._pushLog('info', 'DOCK', 'Rigid docking confirmed. Hard mate achieved, mission complete.');
    }
    return;
  }

  if (rangesTruth.range > CONST.contactRange) return;

  const attErrDeg = rad2deg(qAngleBetween(this.truth.quat, this._desiredDockingQuat(corridor)));
  const result = checkContact(rangesTruth.range, closingRateTruth, rangesTruth.lateral, attErrDeg, CONST.contactLimits);
  this.mission.captureAttempts++;

  if (result.ok){
    this.guidance.phase = 'soft_capture';
    this.guidance.phaseStartMET = this.met;
    this.mission.softCaptured = true;
    this._pushLog('info', 'CONTACT', `Soft capture achieved: range ${rangesTruth.range.toFixed(2)} m, closing ${closingRateTruth.toFixed(3)} m/s, align ${attErrDeg.toFixed(1)} deg.`);
    this.truth.vel = vScale(this.truth.vel, 0.85);
    this.truth.omega = vScale(this.truth.omega, 0.85);
  } else {
    const normal = vNorm(rangesTruth.delta);
    const vAlong = vDot(this.truth.vel, normal);
    if (vAlong > 0){
      this.truth.vel = vSub(this.truth.vel, vScale(normal, vAlong*1.35));
    }
    const push = CONST.contactRange*1.15 - rangesTruth.range;
    if (push > 0) this.truth.pos = vSub(this.truth.pos, vScale(normal, push));
    this._pushLog('caution', 'CONTACT', `Capture rejected (${result.reason}) at range ${rangesTruth.range.toFixed(2)} m. Rebounding for re-attempt.`);
    if (attErrDeg > 45 || rangesTruth.lateral > CONST.keepOutRadius*0.6){
      this.commandAbort();
      this.mission.abortReason = 'unsafe contact geometry';
    }
  }
}

