1	import {
2	  v3, vAdd, vSub, vScale, vDot, vCross, vLen, vNorm, vClone,
3	  qIdentity, qMul, qNorm, qConj, qRotateVec, qFromAxisAngle, qFromTwoVectors,
4	  qAngleBetween, qIntegrate, qAxisAngleError,
5	  mulberry32, makeGaussian
6	} from './engine.mjs';
7	
8	export const FIXED_DT = 0.05;
9	
10	export const CONST = {
11	  n: 0.0011,
12	  chaserMass: 350,
13	  chaserInertia: {x:70, y:100, z:90},
14	  targetInertia: {x:250, y:400, z:340},
15	  thrusterFmax: 6.0,
16	  isp: 220,
17	  g0: 9.80665,
18	  propCapacity: 6.0,
19	  keepOutRadius: 5.0,
20	  contactRange: 0.3,
21	  chaserPortOffset: {x:0.55,y:0,z:0},
22	  targetPortOffset: {x:0.9,y:0,z:0},
23	  waypoints: { hold: 25, proxStart: 25, finalStart: 8 },
24	  corridorHalfAngle: { proximity: 25*Math.PI/180, final: 9*Math.PI/180 },
25	  contactLimits: { contactRange: 0.3, minCloseRate: 0.005, maxCloseRate: 0.10, maxLateral: 0.18, maxAngleDeg: 6 },
26	  closeRateGate: { k: 0.012, min: 0.02, max: 0.35 },
27	};
28	
29	// 8 corner thrusters canted along body diagonals of an asymmetric box (a!=b!=c
30	// so each corner's lever arm couples differently per axis): any single corner
31	// fires a blend of translation + torque, but symmetric 4-thruster subsets give
32	// exactly recoverable *bidirectional* pure force or pure torque about any axis
33	// (verified: for corners grouped by the sign of sy*sz, sx*sz or sx*sy, the two
34	// groups give +/- pure torque about x/y/z with zero net force, and grouping by
35	// sx, sy or sz sign gives +/- pure translation with zero net torque). Plus 4
36	// dedicated axial boosters for the dominant approach/retreat burn.
37	const CORNER = { a: 0.5, b: 0.4, c: 0.3 };
38	function buildThrusterDefs(){
39	  const defs = [];
40	  for (const sx of [1,-1]) for (const sy of [1,-1]) for (const sz of [1,-1]){
41	    const id = `C${sx>0?'+':'-'}${sy>0?'+':'-'}${sz>0?'+':'-'}`;
42	    const pos = { x: sx*CORNER.a, y: sy*CORNER.b, z: sz*CORNER.c };
43	    const dir = vNorm({ x:sx, y:sy, z:sz });
44	    defs.push({ id, pos, dir });
45	  }
46	  defs.push({id:'BX+a', pos:{x:0,y:0.1,z:0.3}, dir:{x:1,y:0,z:0}});
47	  defs.push({id:'BX+b', pos:{x:0,y:-0.1,z:-0.3}, dir:{x:1,y:0,z:0}});
48	  defs.push({id:'BX-a', pos:{x:0,y:0.1,z:-0.3}, dir:{x:-1,y:0,z:0}});
49	  defs.push({id:'BX-b', pos:{x:0,y:-0.1,z:0.3}, dir:{x:-1,y:0,z:0}});
50	  return defs;
51	}
52	const THRUSTER_DEFS = buildThrusterDefs();
53	const N_THRUSTERS = THRUSTER_DEFS.length;
54	
55	function buildBColumns(){
56	  return THRUSTER_DEFS.map(t=>{
57	    const f = vScale(t.dir, CONST.thrusterFmax);
58	    const tq = vScale(vCross(t.pos, t.dir), CONST.thrusterFmax);
59	    return [f.x, f.y, f.z, tq.x, tq.y, tq.z];
60	  });
61	}
62	const B_COLS_FULL = buildBColumns();
63	
64	// Box-constrained (duty in [0,1]) least-squares thruster allocation via
65	// projected Gauss-Seidel coordinate descent: each sweep finds the exact 1D
66	// optimum for one thruster holding the others fixed, then clips to [0,1] and
67	// updates the residual. Monotonically reduces achieved-wrench error and,
68	// unlike a raw pseudo-inverse, never needs an ad-hoc post-hoc clamp that would
69	// distort the achieved force/torque ratio.
70	function allocateNNLS(bCols, wrench, disabledMask, sweeps=18){
71	  const n = bCols.length;
72	  const duty = new Array(n).fill(0);
73	  const colNormSq = bCols.map((c,i)=> disabledMask[i] ? 1e-9 : (c[0]*c[0]+c[1]*c[1]+c[2]*c[2]+c[3]*c[3]+c[4]*c[4]+c[5]*c[5]) || 1e-9);
74	  const residual = wrench.slice();
75	  for (let sweep=0; sweep<sweeps; sweep++){
76	    for (let i=0;i<n;i++){
77	      if (disabledMask[i]) continue;
78	      const col = bCols[i];
79	      let dot = 0;
80	      for (let k=0;k<6;k++) dot += col[k]*residual[k];
81	      let newDuty = duty[i] + dot/colNormSq[i];
82	      if (newDuty < 0) newDuty = 0; else if (newDuty > 1) newDuty = 1;
83	      const delta = newDuty - duty[i];
84	      if (delta !== 0){
85	        for (let k=0;k<6;k++) residual[k] -= col[k]*delta;
86	        duty[i] = newDuty;
87	      }
88	    }
89	  }
90	  return duty;
91	}
92	
93	export const SCENARIOS = {
94	  'nominal': {
95	    label: 'Nominal Rescue',
96	    tumbleDegPerSec: 1.3,
97	    faults: [],
98	  },
99	  'sensor-blackout': {
100	    label: 'Sensor Blackout',
101	    tumbleDegPerSec: 1.3,
102	    faults: [ { type:'blackout', atMET: 70, duration: 55 } ],
103	  },
104	  'stuck-thruster': {
105	    label: 'Stuck Thruster',
106	    tumbleDegPerSec: 1.3,
107	    faults: [ { type:'thruster-stuck', atMET: 25, thrusterId: 'BX+a' } ],
108	  },
109	};
