120	  reset(seed, scenario){
121	    if (scenario) this.scenario = scenario;
122	    if (!this.scenario) this.scenario = 'nominal';
123	    if (seed === undefined || seed === null) seed = this.seed || 1;
124	    this.seed = seed >>> 0;
125	    this.rng = mulberry32(this.seed);
126	    this.gauss = makeGaussian(this.rng);
127	
128	    this.met = 0;
129	    this.paused = false;
130	    this.timeScale = 1;
131	    this.manualMode = false;
132	    this.manualCmd = { force: {x:0,y:0,z:0}, torque: {x:0,y:0,z:0} };
133	
134	    const sc = SCENARIOS[this.scenario] || SCENARIOS.nominal;
135	
136	    this.truth = {
137	      pos: {x:-42, y:6, z:2.5},
138	      vel: {x:0.01, y:0.015, z:0},
139	      quat: qFromAxisAngle({x:0.3,y:1,z:0.2}, deg2rad(35)),
140	      omega: {x:0.002,y:-0.001,z:0.001},
141	    };
142	    const tumbleRad = deg2rad(sc.tumbleDegPerSec);
143	    // spin mostly about the target's own docking-port boresight (body +X, the
144	    // min-inertia principal axis -> dynamically stable, only the intermediate
145	    // axis is chaotic). The port's pointing direction stays nearly fixed while
146	    // its roll continuously advances - a realistic "rotisserie" tumble that a
147	    // chaser can actually rendezvous with, with gentle nutation from the tiny
148	    // perpendicular component for visual character.
149	    const axis = vNorm({x: 1, y: 0.05*(this.rng()-0.5), z: 0.05*(this.rng()-0.5)});
150	    // orient the target so its docking port already faces roughly toward the
151	    // chaser's starting position, instead of an arbitrary side that would force
152	    // a transit straight through the keep-out sphere just to reach the corridor.
153	    const portFacing = qFromTwoVectors({x:1,y:0,z:0}, vNorm(this.truth.pos));
154	    this.target = {
155	      quat: portFacing,
156	      omega: vScale(axis, tumbleRad),
157	    };
158	    const c0 = this._corridorGeometry();
159	    this.corridorAxisSlow = vClone(c0.axis);
160	    this.corridorPortSlow = vClone(c0.portPos);
161	
162	    this.propellantKg = CONST.propCapacity;
163	
164	    this.thrusters = THRUSTER_DEFS.map(t=>({...t, commandedDuty:0, achievedDuty:0}));
165	    this.disabledThrusters = new Set();
166	
167	    this.faults = {
168	      tumbleEnabled: true,
169	      lidarDropout: false,
170	      opticalDropout: false,
171	      stuckThrusterId: null,
172	      scripted: sc.faults.map(f=>({...f, done:false, active:false})),
173	    };
174	
175	    this.fdir = { suspects:{}, detectedId:null, detectMET:null, windowResidual:0 };
176	
177	    this.estimate = {
178	      pos: vAdd(this.truth.pos, {x:this.gauss(1.2),y:this.gauss(1.2),z:this.gauss(1.2)}),
179	      vel: vClone(this.truth.vel),
180	      quat: this.truth.quat,
181	      sigmaPos: {x:1.5,y:1.5,z:1.5},
182	      sigmaVel: {x:0.05,y:0.05,z:0.05},
