257	  frameTick(dtSeconds){
258	    if (this.paused) return;
259	    this.advance(dtSeconds);
260	  }
261	
262	  advance(seconds){
263	    let remaining = seconds;
264	    let guard = 0;
265	    while (remaining > 1e-9 && guard < 200000){
266	      const dt = Math.min(FIXED_DT, remaining);
267	      this._step(dt);
268	      remaining -= dt;
269	      guard++;
270	    }
271	  }
272	
273	  step(dt){ this._step(dt); }
274	
275	  _step(dt){
276	    this._updateScriptedFaults();
277	
278	    const corridor = this._corridorGeometry();
279	    this._updateSlowCorridor(corridor, dt);
280	    const guideCorridor = { portPos: this.corridorPortSlow, axis: this.corridorAxisSlow };
281	
282	    const rangesTruth = this._rangeAndLateral(this.truth.pos, this.truth.quat, corridor);
283	    const rangesEst = this._rangeAndLateral(this.estimate.pos, this.estimate.quat, corridor);
284	    const rangesEstGuide = this._rangeAndLateral(this.estimate.pos, this.estimate.quat, guideCorridor);
285	
286	    const closingRateTruth = this.prevRangeTruth==null ? 0 : (this.prevRangeTruth - rangesTruth.range)/dt;
287	    const closingRateEst = this.prevRangeEst==null ? 0 : (this.prevRangeEst - rangesEst.range)/dt;
288	    this.prevRangeTruth = rangesTruth.range;
289	    this.prevRangeEst = rangesEst.range;
290	
291	    this._updateGuidancePhase(rangesEst, rangesEstGuide, closingRateEst, corridor, guideCorridor);
292	
293	    let desiredForce, desiredTorque;
294	    if (this.manualMode){
295	      desiredForce = qRotateVec(this.estimate.quat, this.manualCmd.force);
296	      desiredTorque = this.manualCmd.torque;
297	    } else {
298	      const activeCorridor = (this.guidance.phase==='final_corridor'||this.guidance.phase==='soft_capture'||this.guidance.phase==='hard_dock') ? corridor : guideCorridor;
299	      const activeRanges = (this.guidance.phase==='final_corridor'||this.guidance.phase==='soft_capture'||this.guidance.phase==='hard_dock') ? rangesEst : rangesEstGuide;
300	      const g = this._computeAutoGuidance(activeRanges, activeCorridor);
301	      desiredForce = g.force; desiredTorque = g.torque;
302	    }
303	
304	    const alloc = this._allocateThrusters(desiredForce, desiredTorque);
305	    this._consumePropellant(alloc.achievedDuties, dt);
306	    this._integrateTruth(alloc.achievedForceLVLH, alloc.achievedTorqueBody, dt);
307	    this._integrateTargetTumble(dt);
308	    this._runSensorsAndEstimator(dt, corridor);
309	    this._runFdir(alloc, dt);
310	
311	    const attErrDeg = rad2deg(qAngleBetween(this.truth.quat, this._desiredDockingQuat(corridor)));
