313	    this._handleContact(rangesTruth, closingRateTruth, corridor, dt);
314	
315	    this._pushHistory(rangesEst.range, closingRateEst, attErrDeg);
316	
317	    this.met += dt;
318	  }
319	
320	  _updateScriptedFaults(){
321	    for (const f of this.faults.scripted){
322	      if (f.done) continue;
323	      if (this.met >= f.atMET && !f.active){
324	        f.active = true;
325	        if (f.type === 'blackout'){
326	          this.faults.lidarDropout = true; this.faults.opticalDropout = true;
327	          this._pushLog('warn', 'SENSOR FAULT', 'Optical navigation and lidar dropped out. Estimator switching to open-loop propagation.');
328	        } else if (f.type === 'thruster-stuck'){
329	          this.faults.stuckThrusterId = f.thrusterId;
330	          this._pushLog('caution', 'ACTUATOR FAULT', `Thruster ${f.thrusterId} commanded but producing no measurable impulse.`);
331	        }
332	      }
333	      if (f.active && f.type === 'blackout' && this.met >= f.atMET + f.duration){
334	        f.active = false; f.done = true;
335	        this.faults.lidarDropout = false; this.faults.opticalDropout = false;
336	        this._pushLog('info', 'SENSOR RECOVERY', 'Optical and lidar returns restored. Estimator uncertainty contracting.');
337	      }
338	      if (f.active && f.type === 'thruster-stuck') f.done = true;
339	    }
340	  }
341	
342	  _updateSlowCorridor(corridor, dt){
343	    const tau = 90;
344	    const alpha = clamp(dt/tau, 0, 1);
345	    this.corridorAxisSlow = vNorm(vAdd(this.corridorAxisSlow, vScale(vSub(corridor.axis, this.corridorAxisSlow), alpha)));
346	    this.corridorPortSlow = vAdd(this.corridorPortSlow, vScale(vSub(corridor.portPos, this.corridorPortSlow), alpha));
347	  }
348	
349	  _corridorGeometry(){
350	    const targetPortPos = qRotateVec(this.target.quat, CONST.targetPortOffset);
351	    const axis = vNorm(qRotateVec(this.target.quat, {x:1,y:0,z:0}));
352	    return { portPos: targetPortPos, axis };
353	  }
354	
355	  _rangeAndLateral(chaserPos, chaserQuat, corridor){
356	    const chaserPortPos = vAdd(chaserPos, qRotateVec(chaserQuat, CONST.chaserPortOffset));
357	    const delta = vSub(corridor.portPos, chaserPortPos);
358	    const range = vLen(delta);
359	    const along = vDot(delta, corridor.axis);
360	    const lateralVec = vSub(delta, vScale(corridor.axis, along));
361	    const lateral = vLen(lateralVec);
362	    // angleFromAxis is the angle between the corridor's outward axis and the
363	    // port-to-chaser direction (note the sign flip from `delta`, which points
364	    // chaser-to-port): a well-aligned chaser sits *along* the outward axis, so
365	    // without the flip this would measure the supplementary (~180 deg) angle.
366	    let angleFromAxis = 0;
367	    if (range > 1e-6) angleFromAxis = Math.acos(clamp(-along/range, -1, 1));
368	    return { chaserPortPos, delta, range, along, lateral, angleFromAxis };
369	  }
370	
371	  _desiredDockingQuat(corridor){
372	    // chaser +X should point opposite the corridor axis (facing the port)
373	    return qFromTwoVectors({x:1,y:0,z:0}, vScale(corridor.axis, -1));
374	  }
375	
376	  _updateGuidancePhase(rangesEst, rangesEstGuide, closingRateEst, corridor, guideCorridor){
377	    const g = this.guidance;
378	    if (this.mission.aborted || g.phase === 'abort'){ g.phase = 'abort'; return; }
379	    if (g.phase === 'hard_dock') return;
380	    const elapsedInPhase = this.met - g.phaseStartMET;
381	
382	    const transition = (next, reason)=>{
383	      g.phase = next; g.phaseStartMET = this.met; g.lastReason = reason; g.holdReason = null;
384	      this._pushLog('info', 'PHASE', reason);
385	    };
386	
387	    switch(g.phase){
388	      case 'acquire':
389	        if (elapsedInPhase > 4){
390	          transition('far_approach', 'Target lock established. Beginning far-field approach toward hold point.');
391	        }
392	        break;
393	      case 'far_approach':
394	        if (rangesEstGuide.range <= CONST.waypoints.hold + 1.0 && Math.abs(closingRateEst) < 0.15){
395	          transition('hold_point', `Reached hold point at ${rangesEstGuide.range.toFixed(1)} m. Stationkeeping to verify navigation and attitude sync.`);
396	        }
397	        break;
398	      case 'hold_point': {
399	        const navGood = this._navUncertaintyScalar() < 0.9;
400	        const attErrDeg = rad2deg(qAngleBetween(this.estimate.quat, this._desiredDockingQuat(guideCorridor)));
401	        if (navGood && attErrDeg < 20 && elapsedInPhase > 8){
402	          transition('proximity_approach', 'Navigation solid and attitude synced. Cleared for proximity approach.');
403	        } else if (!navGood){
404	          g.holdReason = 'Holding: navigation uncertainty above threshold for proximity clearance.';
405	        }
406	        break;
407	      }
408	      case 'proximity_approach': {
409	        const navBad = this._navUncertaintyScalar() > 1.6;
410	        if (navBad){
411	          transition('hold_point', 'Navigation uncertainty exceeded safe threshold during proximity ops. Reverting to hold point.');
412	          break;
413	        }
414	        if (rangesEst.range <= CONST.waypoints.finalStart + 0.5 && rangesEst.lateral < 1.5){
415	          transition('final_corridor', `Entering final approach corridor at ${rangesEst.range.toFixed(1)} m.`);
416	        }
417	        break;
418	      }
419	      case 'final_corridor': {
420	        const navBad = this._navUncertaintyScalar() > 1.4;
421	        if (navBad){
422	          transition('hold_point', 'Navigation degraded inside final corridor. Retreating to hold point for safety.');
423	          break;
424	        }
425	        break; // contact handled in _handleContact
426	      }
427	      case 'soft_capture':
428	        break;
429	    }
430	  }
431	
432	  _navUncertaintyScalar(){
433	    const e = this.estimate;
434	    return (e.sigmaPos.x+e.sigmaPos.y+e.sigmaPos.z)/3;
435	  }
436	
437	  _computeAutoGuidance(rangesEst, corridor){
438	    const phase = this.guidance.phase;
439	    const m = CONST.chaserMass;
440	    const pos = this.estimate.pos, vel = this.estimate.vel;
441	    const n = CONST.n;
442	    const naturalAccel = { x: 2*n*vel.y+3*n*n*pos.x, y: -2*n*vel.x, z: -n*n*pos.z };
443	
444	    let vDes = {x:0,y:0,z:0};
445	    let posErrGain = 0;
446	    let velGain = 0.9;
447	
448	    const towardPort = vNorm(rangesEst.delta);
449	
450	    if (phase === 'abort'){
451	      const target = vAdd(corridor.portPos, vScale(corridor.axis, CONST.waypoints.hold*1.6));
452	      const err = vSub(target, this.estimate.pos);
453	      vDes = vScale(vNorm(err), clamp(vLen(err)/120, 0.02, 0.25));
454	      velGain = 0.7;
455	    } else if (phase === 'acquire'){
456	      vDes = {x:0,y:0,z:0}; velGain = 0.6;
457	    } else if (phase === 'far_approach'){
458	      const wp = vAdd(corridor.portPos, vScale(corridor.axis, CONST.waypoints.hold));
459	      const err = vSub(wp, this.estimate.pos);
460	      const dist = vLen(err);
461	      const speed = clamp(dist/120, 0.05, 0.6);
462	      vDes = dist>0.05 ? vScale(vNorm(err), speed) : {x:0,y:0,z:0};
463	      velGain = 0.8;
464	    } else if (phase === 'hold_point'){
465	      const wp = vAdd(corridor.portPos, vScale(corridor.axis, CONST.waypoints.hold));
466	      posErrGain = 0.02;
467	      vDes = {x:0,y:0,z:0};
468	      const err = vSub(wp, this.estimate.pos);
469	      vDes = vScale(err, 0.02);
470	      velGain = 1.0;
471	    } else if (phase === 'proximity_approach'){
472	      const wp = vAdd(corridor.portPos, vScale(corridor.axis, CONST.waypoints.finalStart));
473	      const alongErr = vDot(vSub(wp, this.estimate.pos), corridor.axis);
474	      const lateralVec = vSub(vSub(wp, this.estimate.pos), vScale(corridor.axis, alongErr));
475	      const gateAlong = clamp(rangesEst.range*CONST.closeRateGate.k*2.2, CONST.closeRateGate.min, CONST.closeRateGate.max);
476	      const speedAlong = clamp(alongErr/70, -gateAlong, gateAlong);
477	      const gateLateral = 0.22;
478	      let vLat = vScale(lateralVec, 0.06);
479	      if (vLen(vLat) > gateLateral) vLat = vScale(vNorm(vLat), gateLateral);
480	      vDes = vAdd(vScale(corridor.axis, speedAlong), vLat);
481	      velGain = 0.9;
482	    } else if (phase === 'final_corridor'){
483	      const alongErr = vDot(vSub(corridor.portPos, rangesEst.chaserPortPos), corridor.axis);
484	      const lateralVec = vSub(vSub(corridor.portPos, rangesEst.chaserPortPos), vScale(corridor.axis, alongErr));
485	      const gateAlong = clamp(rangesEst.range*0.028, 0.015, 0.085);
486	      const speedAlong = clamp(alongErr/45, -gateAlong, gateAlong);
487	      const gateLateral = 0.2;
488	      let vLat = vScale(lateralVec, 0.16);
489	      if (vLen(vLat) > gateLateral) vLat = vScale(vNorm(vLat), gateLateral);
490	      vDes = vAdd(vScale(corridor.axis, speedAlong), vLat);
491	      velGain = 1.1;
492	    } else if (phase === 'soft_capture' || phase === 'hard_dock'){
493	      vDes = {x:0,y:0,z:0}; velGain = 1.4; posErrGain = 0.05;
494	    }
495	
496	    let forceMag;
497	    if (phase==='far_approach') forceMag = 3.4;
498	    else if (phase==='hold_point') forceMag = 1.6;
499	    else if (phase==='proximity_approach') forceMag = 2.2;
500	    else if (phase==='final_corridor') forceMag = 1.2;
501	    else if (phase==='soft_capture'||phase==='hard_dock') forceMag = 1.0;
502	    else forceMag = 2.0;
503	
504	    let force = vScale({
505	      x: -naturalAccel.x + velGain*(vDes.x - this.estimate.vel.x),
506	      y: -naturalAccel.y + velGain*(vDes.y - this.estimate.vel.y),
507	      z: -naturalAccel.z + velGain*(vDes.z - this.estimate.vel.z),
508	    }, m);
509	    const fl = vLen(force);
510	    if (fl > forceMag*12) force = vScale(force, (forceMag*12)/fl);
511	
512	    const qDes = this._desiredDockingQuat(corridor);
513	    const axisErr = qAxisAngleError(this.estimate.quat, qDes);
514	    const I = CONST.chaserInertia;
515	    const omega = this.estimate.omega || {x:0,y:0,z:0};
516	    const Kp_att = (phase==='final_corridor'||phase==='soft_capture'||phase==='hard_dock') ? 3.2 : 1.6;
517	    const Kd_att = (phase==='final_corridor'||phase==='soft_capture'||phase==='hard_dock') ? 6.5 : 4.0;
518	    const gyro = vCross(omega, {x:I.x*omega.x, y:I.y*omega.y, z:I.z*omega.z});
519	    let torque = {
520	      x: I.x*(Kp_att*axisErr.x - Kd_att*omega.x) + gyro.x,
521	      y: I.y*(Kp_att*axisErr.y - Kd_att*omega.y) + gyro.y,
522	      z: I.z*(Kp_att*axisErr.z - Kd_att*omega.z) + gyro.z,
523	    };
524	    const tl = vLen(torque);
525	    const maxT = 4.0;
526	    if (tl > maxT) torque = vScale(torque, maxT/tl);
527	
528	    return { force, torque };
529	  }
