531	  _allocateThrusters(desiredForceLVLH, desiredTorqueBody){
532	    const desiredForceBody = qRotateVec(qConj(this.truth.quat), desiredForceLVLH);
533	    const wrench = [desiredForceBody.x, desiredForceBody.y, desiredForceBody.z, desiredTorqueBody.x, desiredTorqueBody.y, desiredTorqueBody.z];
534	
535	    const disabledMask = THRUSTER_DEFS.map(t=> this.disabledThrusters.has(t.id));
536	    const duty = allocateNNLS(B_COLS_FULL, wrench, disabledMask);
537	
538	    const achieved = new Array(N_THRUSTERS).fill(0);
539	    for (let i=0;i<N_THRUSTERS;i++){
540	      let d = duty[i];
541	      const isStuck = this.thrusters[i].id === this.faults.stuckThrusterId;
542	      this.thrusters[i].commandedDuty = d;
543	      if (isStuck) d = 0;
544	      achieved[i] = d;
545	      this.thrusters[i].achievedDuty = d;
546	    }
547	
548	    let achievedForceBody = {x:0,y:0,z:0};
549	    let achievedTorqueBody = {x:0,y:0,z:0};
550	    for (let i=0;i<N_THRUSTERS;i++){
551	      const f = vScale(THRUSTER_DEFS[i].dir, CONST.thrusterFmax*achieved[i]);
552	      const tq = vScale(vCross(THRUSTER_DEFS[i].pos, THRUSTER_DEFS[i].dir), CONST.thrusterFmax*achieved[i]);
553	      achievedForceBody = vAdd(achievedForceBody, f);
554	      achievedTorqueBody = vAdd(achievedTorqueBody, tq);
555	    }
556	    const achievedForceLVLH = qRotateVec(this.truth.quat, achievedForceBody);
557	
558	    return { achievedDuties: achieved, achievedForceLVLH, achievedTorqueBody, desiredWrench: wrench };
559	  }
560	
561	  _consumePropellant(achievedDuties, dt){
562	    let totalThrust = 0;
563	    for (let i=0;i<N_THRUSTERS;i++) totalThrust += CONST.thrusterFmax*achievedDuties[i];
564	    const mdot = totalThrust/(CONST.isp*CONST.g0);
565	    this.propellantKg = Math.max(0, this.propellantKg - mdot*dt);
566	  }
567	
568	  _integrateTruth(forceLVLH, torqueBody, dt){
569	    const m = CONST.chaserMass;
570	    const n = CONST.n;
571	    const s = this.truth;
572	    const deriv = (pos, vel)=>({
573	      dpos: vClone(vel),
574	      dvel: {
575	        x: 2*n*vel.y + 3*n*n*pos.x + forceLVLH.x/m,
576	        y: -2*n*vel.x + forceLVLH.y/m,
577	        z: -n*n*pos.z + forceLVLH.z/m,
578	      }
579	    });
580	    const k1 = deriv(s.pos, s.vel);
581	    const k2 = deriv(vAdd(s.pos, vScale(k1.dpos, dt/2)), vAdd(s.vel, vScale(k1.dvel, dt/2)));
582	    const k3 = deriv(vAdd(s.pos, vScale(k2.dpos, dt/2)), vAdd(s.vel, vScale(k2.dvel, dt/2)));
583	    const k4 = deriv(vAdd(s.pos, vScale(k3.dpos, dt)), vAdd(s.vel, vScale(k3.dvel, dt)));
584	    s.pos = vAdd(s.pos, vScale(vAdd(vAdd(k1.dpos, vScale(k2.dpos,2)), vAdd(vScale(k3.dpos,2), k4.dpos)), dt/6));
585	    s.vel = vAdd(s.vel, vScale(vAdd(vAdd(k1.dvel, vScale(k2.dvel,2)), vAdd(vScale(k3.dvel,2), k4.dvel)), dt/6));
586	
587	    const I = CONST.chaserInertia;
588	    const omegaDeriv = (omega)=>{
589	      const Iomega = {x:I.x*omega.x, y:I.y*omega.y, z:I.z*omega.z};
590	      const gyro = vCross(omega, Iomega);
591	      return { x:(torqueBody.x-gyro.x)/I.x, y:(torqueBody.y-gyro.y)/I.y, z:(torqueBody.z-gyro.z)/I.z };
592	    };
593	    const o1 = omegaDeriv(s.omega);
594	    const o2 = omegaDeriv(vAdd(s.omega, vScale(o1, dt/2)));
595	    const o3 = omegaDeriv(vAdd(s.omega, vScale(o2, dt/2)));
596	    const o4 = omegaDeriv(vAdd(s.omega, vScale(o3, dt)));
597	    const omegaNew = vAdd(s.omega, vScale(vAdd(vAdd(o1, vScale(o2,2)), vAdd(vScale(o3,2), o4)), dt/6));
598	    const omegaAvg = vScale(vAdd(s.omega, omegaNew), 0.5);
599	    s.quat = qIntegrate(s.quat, omegaAvg, dt);
600	    s.omega = omegaNew;
601	  }
602	
603	  _integrateTargetTumble(dt){
604	    if (!this.faults.tumbleEnabled){ return; }
605	    const I = CONST.targetInertia;
606	    const t = this.target;
607	    const omegaDeriv = (omega)=>{
608	      const Iomega = {x:I.x*omega.x, y:I.y*omega.y, z:I.z*omega.z};
609	      const gyro = vCross(omega, Iomega);
610	      return { x:-gyro.x/I.x, y:-gyro.y/I.y, z:-gyro.z/I.z };
611	    };
612	    const o1 = omegaDeriv(t.omega);
613	    const o2 = omegaDeriv(vAdd(t.omega, vScale(o1, dt/2)));
614	    const o3 = omegaDeriv(vAdd(t.omega, vScale(o2, dt/2)));
615	    const o4 = omegaDeriv(vAdd(t.omega, vScale(o3, dt)));
616	    const omegaNew = vAdd(t.omega, vScale(vAdd(vAdd(o1, vScale(o2,2)), vAdd(vScale(o3,2), o4)), dt/6));
617	    const omegaAvg = vScale(vAdd(t.omega, omegaNew), 0.5);
618	    t.quat = qIntegrate(t.quat, omegaAvg, dt);
619	    t.omega = omegaNew;
620	  }
621	
622	  _runSensorsAndEstimator(dt, corridor){
623	    const e = this.estimate;
624	    const lidarActive = !this.faults.lidarDropout;
625	    const opticalActive = !this.faults.opticalDropout;
626	
627	    // prediction (uses same known applied accel implicitly via velocity persistence + natural dynamics)
628	    const n = CONST.n;
629	    const natAccel = { x: 2*n*e.vel.y+3*n*n*e.pos.x, y:-2*n*e.vel.x, z:-n*n*e.pos.z };
630	    e.vel = vAdd(e.vel, vScale(natAccel, dt));
631	    e.pos = vAdd(e.pos, vScale(e.vel, dt));
632	
633	    const qProcess = 0.0009;
634	    e.sigmaPos = { x: Math.sqrt(e.sigmaPos.x**2 + (qProcess*dt)**2)+0*e.sigmaPos.x*0.0006,
635	                    y: Math.sqrt(e.sigmaPos.y**2 + (qProcess*dt)**2),
636	                    z: Math.sqrt(e.sigmaPos.z**2 + (qProcess*dt)**2) };
637	    e.sigmaPos = { x: e.sigmaPos.x*(1+0.0008), y: e.sigmaPos.y*(1+0.0008), z: e.sigmaPos.z*(1+0.0008) };
638	    e.sigmaVel = { x: e.sigmaVel.x*(1+0.0006)+1e-5, y: e.sigmaVel.y*(1+0.0006)+1e-5, z: e.sigmaVel.z*(1+0.0006)+1e-5 };
639	    e.sigmaAtt = e.sigmaAtt*(1+0.0006) + 1e-6;
640	
641	    if (lidarActive){
642	      const measPos = vAdd(this.truth.pos, {x:this.gauss(0.06),y:this.gauss(0.06),z:this.gauss(0.06)});
643	      const R = 0.06;
644	      ['x','y','z'].forEach(ax=>{
645	        const P = e.sigmaPos[ax]**2;
646	        const K = P/(P+R*R);
647	        e.pos[ax] = e.pos[ax] + K*(measPos[ax]-e.pos[ax]);
648	        e.sigmaPos[ax] = Math.sqrt((1-K)*P);
649	      });
650	      const measVel = vAdd(this.truth.vel, {x:this.gauss(0.004),y:this.gauss(0.004),z:this.gauss(0.004)});
651	      const Rv = 0.004;
652	      ['x','y','z'].forEach(ax=>{
653	        const P = e.sigmaVel[ax]**2;
654	        const K = P/(P+Rv*Rv);
655	        e.vel[ax] = e.vel[ax] + K*(measVel[ax]-e.vel[ax]);
656	        e.sigmaVel[ax] = Math.sqrt((1-K)*P);
657	      });
658	    } else if (opticalActive){
659	      const measPos = vAdd(this.truth.pos, {x:this.gauss(0.9),y:this.gauss(0.9),z:this.gauss(0.9)});
660	      const R = 0.9;
661	      ['x','y','z'].forEach(ax=>{
662	        const P = e.sigmaPos[ax]**2;
663	        const K = P/(P+R*R);
664	        e.pos[ax] = e.pos[ax] + K*(measPos[ax]-e.pos[ax]);
665	        e.sigmaPos[ax] = Math.sqrt((1-K)*P);
666	      });
667	    }
668	
669	    if (opticalActive){
670	      e.quat = this.truth.quat;
671	      e.sigmaAtt = Math.max(deg2rad(0.6), e.sigmaAtt*0.7);
672	      e.targetQuat = this.target.quat;
673	      e.targetOmega = vClone(this.target.omega);
674	      e.targetLock = true;
675	    } else {
676	      e.quat = qIntegrate(e.quat, this.truth.omega, dt);
677	      e.targetQuat = qIntegrate(e.targetQuat, e.targetOmega, dt);
678	      e.targetLock = false;
679	    }
680	    e.omega = vClone(this.truth.omega);
681	  }
682	
683	  _runFdir(alloc, dt){
684	    if (this.faults.stuckThrusterId && this.disabledThrusters.size===0 && !this.fdir.detectedId){
685	      const id = this.faults.stuckThrusterId;
686	      const idx = THRUSTER_DEFS.findIndex(t=>t.id===id);
687	      const commandedHigh = this.thrusters[idx].commandedDuty > 0.12;
688	      if (commandedHigh){
689	        this.fdir.windowResidual += dt;
690	      } else {
691	        this.fdir.windowResidual = Math.max(0, this.fdir.windowResidual-dt*0.5);
692	      }
693	      if (this.fdir.windowResidual > 1.2){
694	        this.fdir.detectedId = id;
695	        this.fdir.detectMET = this.met;
696	        this.disabledThrusters.add(id);
697	        this._pushLog('warn', 'FDIR', `Fault isolated to thruster ${id}. Reallocating RCS authority to remaining thrusters.`);
698	      }
699	    }
700	  }
701	
702	  _updateSafety(rangesTruth, closingRateTruth, corridor, attErrDeg){
703	    const s = this.safety;
704	    const inSphere = rangesTruth.range < CONST.keepOutRadius;
705	    const halfAngle = (this.guidance.phase==='final_corridor'||this.guidance.phase==='soft_capture') ? CONST.corridorHalfAngle.final : CONST.corridorHalfAngle.proximity;
706	    const insideCorridor = rangesTruth.angleFromAxis < halfAngle;
707	    s.keepOutViolation = inSphere && !insideCorridor;
708	    const gate = clamp(rangesTruth.range*CONST.closeRateGate.k, CONST.closeRateGate.min, CONST.closeRateGate.max);
709	    s.closingRateOk = closingRateTruth <= gate*1.4;
710	    s.alignmentOk = attErrDeg < 35;
711	    s.margins = {
712	      keepOut: inSphere ? (insideCorridor ? 1 : 0) : (rangesTruth.range - CONST.keepOutRadius),
713	      rate: gate*1.4 - closingRateTruth,
714	      lateral: CONST.contactLimits.maxLateral - rangesTruth.lateral,
715	      angle: CONST.contactLimits.maxAngleDeg - attErrDeg,
716	    };
717	    if (s.keepOutViolation && !this.mission.aborted && this.guidance.phase!=='abort' && rangesTruth.range > CONST.contactRange){
718	      this.commandAbort();
719	      this.mission.abortReason = 'keep-out violation';
720	      this._pushLog('caution', 'SAFETY', 'Keep-out sphere violated outside approach corridor. Autonomous abort triggered.');
721	    }
722	  }
723	
724	  _handleContact(rangesTruth, closingRateTruth, corridor, dt){
725	    if (this.mission.docked) return;
726	    if (this.guidance.phase === 'abort') return;
727	
728	    // Already latched in soft capture: the mechanism is actively damping
729	    // relative motion toward zero, so re-applying the *initial* contact gate
730	    // (which requires a minimum closing rate) would immediately "reject" the
731	    // very capture it just confirmed. Only watch for gross containment loss.
732	    if (this.guidance.phase === 'soft_capture'){
733	      if (rangesTruth.range > CONST.contactRange*3.5){
734	        this.guidance.phase = 'final_corridor';
735	        this.guidance.phaseStartMET = this.met;
736	        this._pushLog('caution', 'CONTACT', 'Soft capture containment lost. Re-attempting final approach.');
737	        return;
738	      }
739	      this.truth.vel = vScale(this.truth.vel, 0.85);
740	      this.truth.omega = vScale(this.truth.omega, 0.85);
741	      const stableFor = this.met - this.guidance.phaseStartMET;
742	      if (stableFor > 3.0){
743	        this.guidance.phase = 'hard_dock';
744	        this.mission.docked = true;
745	        this._pushLog('info', 'DOCK', 'Rigid docking confirmed. Hard mate achieved, mission complete.');
746	      }
747	      return;
748	    }
749	
750	    if (rangesTruth.range > CONST.contactRange) return;
751	
752	    const attErrDeg = rad2deg(qAngleBetween(this.truth.quat, this._desiredDockingQuat(corridor)));
753	    const result = checkContact(rangesTruth.range, closingRateTruth, rangesTruth.lateral, attErrDeg, CONST.contactLimits);
754	    this.mission.captureAttempts++;
755	
756	    if (result.ok){
757	      this.guidance.phase = 'soft_capture';
758	      this.guidance.phaseStartMET = this.met;
759	      this.mission.softCaptured = true;
760	      this._pushLog('info', 'CONTACT', `Soft capture achieved: range ${rangesTruth.range.toFixed(2)} m, closing ${closingRateTruth.toFixed(3)} m/s, align ${attErrDeg.toFixed(1)} deg.`);
761	      this.truth.vel = vScale(this.truth.vel, 0.85);
762	      this.truth.omega = vScale(this.truth.omega, 0.85);
763	    } else {
764	      const normal = vNorm(rangesTruth.delta);
765	      const vAlong = vDot(this.truth.vel, normal);
766	      if (vAlong > 0){
767	        this.truth.vel = vSub(this.truth.vel, vScale(normal, vAlong*1.35));
768	      }
769	      const push = CONST.contactRange*1.15 - rangesTruth.range;
770	      if (push > 0) this.truth.pos = vSub(this.truth.pos, vScale(normal, push));
771	      this._pushLog('caution', 'CONTACT', `Capture rejected (${result.reason}) at range ${rangesTruth.range.toFixed(2)} m. Rebounding for re-attempt.`);
772	      if (attErrDeg > 45 || rangesTruth.lateral > CONST.keepOutRadius*0.6){
773	        this.commandAbort();
774	        this.mission.abortReason = 'unsafe contact geometry';
775	      }
776	    }
777	  }
778	
779	  _pushHistory(range, closingRate, attErrDeg){
780	    const h = this.history;
781	    h.t.push(this.met);
782	    h.range.push(range);
783	    h.closingRate.push(closingRate);
784	    h.propellant.push(this.propellantKg);
785	    h.attErr.push(attErrDeg);
786	    h.navUncertainty.push(this._navUncertaintyScalar());
787	    if (h.t.length > this.historyCap){
788	      h.t.shift(); h.range.shift(); h.closingRate.shift(); h.propellant.shift(); h.attErr.shift(); h.navUncertainty.shift();
789	    }
790	  }
791	
792	  snapshot(){
793	    const corridor = this._corridorGeometry();
794	    const rangesTruth = this._rangeAndLateral(this.truth.pos, this.truth.quat, corridor);
795	    const rangesEst = this._rangeAndLateral(this.estimate.pos, this.estimate.quat, corridor);
796	    return {
797	      met: this.met,
798	      seed: this.seed,
799	      scenario: this.scenario,
800	      paused: this.paused,
801	      manualMode: this.manualMode,
802	      truth: {
803	        pos: vClone(this.truth.pos), vel: vClone(this.truth.vel),
804	        quat: {...this.truth.quat}, omega: vClone(this.truth.omega),
805	        targetQuat: {...this.target.quat}, targetOmega: vClone(this.target.omega),
806	      },
807	      estimate: {
808	        pos: vClone(this.estimate.pos), vel: vClone(this.estimate.vel),
809	        quat: {...this.estimate.quat}, sigmaPos: {...this.estimate.sigmaPos}, sigmaVel: {...this.estimate.sigmaVel},
810	        sigmaAtt: this.estimate.sigmaAtt, targetLock: this.estimate.targetLock,
811	      },
812	      guidance: { phase: this.guidance.phase, holdReason: this.guidance.holdReason, lastReason: this.guidance.lastReason },
813	      actuators: {
814	        propellantKg: this.propellantKg, propellantPct: this.propellantKg/CONST.propCapacity,
815	        thrusters: this.thrusters.map(t=>({id:t.id, commanded:t.commandedDuty, achieved:t.achievedDuty, stuck: t.id===this.faults.stuckThrusterId})),
816	      },
817	      safety: { ...this.safety, margins: {...this.safety.margins} },
818	      sensors: { lidarActive: !this.faults.lidarDropout, opticalActive: !this.faults.opticalDropout },
819	      faults: { ...this.faults, scripted: undefined },
820	      mission: { ...this.mission },
821	      range: rangesTruth.range,
822	      rangeEst: rangesEst.range,
823	      lateral: rangesTruth.lateral,
824	    };
825	  }
826	}
827	
828	export function checkContact(range, closingRate, lateralOffset, angleErrorDeg, limits){
829	  if (range > limits.contactRange) return { ok:false, reason:'out-of-range' };
830	  if (closingRate < limits.minCloseRate) return { ok:false, reason:'closing-rate-too-low' };
831	  if (closingRate > limits.maxCloseRate) return { ok:false, reason:'closing-rate-too-high' };
832	  if (lateralOffset > limits.maxLateral) return { ok:false, reason:'lateral-offset' };
833	  if (angleErrorDeg > limits.maxAngleDeg) return { ok:false, reason:'angle-misalign' };
834	  return { ok:true, reason:'nominal' };
835	}
836	
837	export function isFiniteVec(v){ return Number.isFinite(v.x)&&Number.isFinite(v.y)&&Number.isFinite(v.z); }
838	export function isFiniteQuat(q){ return Number.isFinite(q.x)&&Number.isFinite(q.y)&&Number.isFinite(q.z)&&Number.isFinite(q.w); }
