function startCamTransition(){
  camTransition.fromPos.copy(camera.position);
  camTransition.fromQuat.copy(camera.quaternion);
  camTransition.t = 0; camTransition.active = true;
}

function setCamMode(mode){
  if (!camModes.includes(mode)) return;
  camMode = mode;
  orbitControls.enabled = (mode === 'free');
  document.getElementById('cam-mode-label').textContent = camLabels[mode];
  document.getElementById('reticle').style.display = (mode==='docking-port') ? 'block' : 'none';
  document.querySelectorAll('.cam-btn').forEach(b=> b.classList.toggle('active', b.dataset.cam===mode));
  startCamTransition();
  if (mode === 'free'){
    const chaserP = toThreeV(liveSim.truth.pos);
    orbitControls.target.copy(chaserP.clone().multiplyScalar(0.5));
  }
}

function resetView(){
  if (camMode === 'free'){
    orbitControls.target.set(0,0,0);
    camera.position.set(30,20,30);
  }
  startCamTransition();
}

